begin;

insert into public.categories (id, slug, name, description, position) values
  ('10000000-0000-4000-a000-000000000001', 'epices', 'Épices & aromates', 'Poivres, graines, condiments et mélanges d''épices des cuisines africaines, souvent introuvables en grande surface.', 1),
  ('10000000-0000-4000-a000-000000000002', 'cereales', 'Farines & céréales', 'Fonio, attiéké, couscous de mil : les céréales anciennes et les semoules du continent.', 2),
  ('10000000-0000-4000-a000-000000000003', 'feuilles', 'Feuilles & fleurs séchées', 'Feuilles de ndolé, de manioc ou de moringa, fleurs d''hibiscus : les feuilles et fleurs des sauces et des boissons africaines.', 3),
  ('10000000-0000-4000-a000-000000000004', 'poissons', 'Poissons & fumés', 'Poissons séchés, fumés ou fermentés et crevettes séchées, les exhausteurs de goût de la cuisine africaine.', 4),
  ('10000000-0000-4000-a000-000000000005', 'huiles', 'Huiles & pâtes', 'Huile de palme rouge, pâte d''arachide, pulpe de noix de palme : la base des grandes sauces.', 5),
  ('10000000-0000-4000-a000-000000000008', 'snacks', 'Snacks & fruits secs', 'Chips de plantain, dattes, souchet, biltong, bitter kola : de quoi grignoter à l''africaine.', 6),
  ('10000000-0000-4000-a000-000000000006', 'cafes-thes', 'Cafés & thés', 'Cafés d''Éthiopie, du Kenya ou du Rwanda, rooibos, kinkeliba et thé vert pour l''ataya : les boissons chaudes du continent.', 7),
  ('10000000-0000-4000-a000-000000000007', 'ustensiles', 'Ustensiles', 'Mortiers, couscoussiers, marmites, théières : le matériel pour cuisiner et servir les plats africains.', 8)
on conflict (id) do nothing;

insert into public.products (id, slug, name, category_id, short_description, description, origin_country, origin_region, producer, images, composition, allergens, usage_tips, conservation, tags, amazon_asin, is_active, featured, created_at) values
  ('20000000-0000-4000-a000-000000000001', 'poivre-de-penja', 'Poivre blanc de Penja', '10000000-0000-4000-a000-000000000001', 'Poivre blanc de la région de Penja, au Cameroun, au piquant franc et aux notes boisées et musquées.', 'Le poivre de Penja est cultivé dans la région de Penja, au Cameroun, qui a donné son nom à cette appellation. Le poivre blanc est obtenu à partir de baies mûres débarrassées de leur enveloppe : il offre un piquant net et des notes boisées et musquées.

Dans la cuisine camerounaise, il relève le poisson braisé, le ndolé et les viandes grillées. Il se moud de préférence au dernier moment.', 'Cameroun', 'Penja', null, array['/products/poivre-de-penja.webp']::text[], 'Poivre blanc en grains (Piper nigrum).', '{}'::text[], 'Moudre en fin de cuisson sur les poissons braisés, le ndolé ou les viandes grillées pour garder tout son parfum.', 'Au sec, à l''abri de la lumière, dans un contenant fermé.', array['poivre', 'Cameroun']::text[], 'B000PBXHBS', true, true, '2026-01-01T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000002', 'soumbala', 'Soumbala (nététou)', '10000000-0000-4000-a000-000000000001', 'Graines de néré fermentées, le condiment de caractère des sauces d''Afrique de l''Ouest et du Sahel.', 'Le soumbala, appelé nététou au Sénégal, est obtenu à partir des graines de néré, un arbre des savanes d''Afrique de l''Ouest, cuites puis fermentées. Il se présente en boules, en galettes ou en poudre, et dégage une odeur puissante.

Utilisé en petite quantité, il donne au mafé, au riz gras et aux sauces feuilles un goût profond et savoureux, proche de l''umami.', 'Afrique de l''Ouest', null, null, array['/products/soumbala.webp']::text[], 'Graines de néré (Parkia biglobosa) fermentées ; peut contenir du sel selon la préparation, voir l''étiquette.', '{}'::text[], 'Écraser un petit morceau dans le mafé, les sauces feuilles ou le riz gras en début de cuisson : une petite quantité suffit.', 'Au sec, dans une boîte hermétique, car son odeur est puissante.', array['fermenté', 'umami']::text[], 'B0CQKHMT2Y', true, true, '2026-01-02T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000003', 'berbere', 'Berbéré d''Éthiopie', '10000000-0000-4000-a000-000000000001', 'Le mélange d''épices rouge et relevé de la cuisine éthiopienne, base des wats mijotés.', 'Le berbéré est le mélange d''épices emblématique de la cuisine éthiopienne. Sa composition varie selon les recettes, mais on y trouve le plus souvent du piment, du fenugrec, du gingembre, de l''ail et des épices chaudes comme le clou de girofle.

Il parfume et colore les wats, ces ragoûts mijotés servis sur l''injera : doro wat au poulet, misir wat aux lentilles corail.', 'Éthiopie', null, null, array['/products/berbere.webp']::text[], 'Mélange d''épices à base de piment ; composition exacte selon la marque, voir l''étiquette.', '{}'::text[], 'Base du doro wat et du misir wat : faire revenir le berbéré dans le beurre ou l''huile avec les oignons avant d''ajouter les autres ingrédients.', 'Au sec, à l''abri de la lumière, dans un contenant fermé.', array['mélange', 'piquant']::text[], 'B079R281WV', true, false, '2026-01-03T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000004', 'yaji-suya', 'Yaji, épices à suya', '10000000-0000-4000-a000-000000000001', 'Le mélange arachide-piment qui enrobe le suya, la brochette grillée vendue dans les rues du Nigeria.', 'Le yaji est le mélange d''épices qui enrobe le suya, la brochette de viande grillée vendue dans les rues du Nigeria. Il associe généralement de l''arachide grillée moulue (kuli-kuli), du piment, du gingembre et d''autres épices.

Il donne à la viande un enrobage relevé et légèrement croustillant ; on l''utilise aussi sur le poulet, le poisson ou les légumes grillés.', 'Nigeria', null, null, array['/products/yaji-suya.webp']::text[], 'Arachide grillée moulue, piment, épices ; composition exacte selon la marque, voir l''étiquette.', array['arachide']::text[], 'Frotter la viande avec le yaji avant de la griller, puis en saupoudrer à la sortie du feu.', 'Au sec, dans un contenant fermé.', array['grillade', 'piquant']::text[], 'B0CTTM79ZR', true, true, '2026-01-04T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000005', 'poivre-de-selim', 'Poivre de Selim (djar)', '10000000-0000-4000-a000-000000000001', 'Gousses sombres aux notes fumées, résineuses et musquées, qui parfument le café Touba et les bouillons.', 'Le poivre de Selim est le fruit du Xylopia aethiopica, un arbre d''Afrique tropicale. Ses longues gousses sombres, appelées djar au Sénégal, ont un parfum résineux, musqué et poivré.

Au Sénégal, il est torréfié avec le café pour donner le café Touba ; ailleurs en Afrique de l''Ouest et centrale, il parfume les bouillons, les soupes et les marinades.', null, null, null, array['/products/poivre-de-selim.webp']::text[], 'Gousses de poivre de Selim (Xylopia aethiopica).', '{}'::text[], 'Écraser les gousses et les infuser dans les bouillons, ou les moudre avec le café.', 'Au sec, à l''abri de la lumière, dans un contenant fermé.', array['épice', 'gousses']::text[], 'B07GFN2J77', true, false, '2026-01-05T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000006', 'fonio', 'Fonio précuit', '10000000-0000-4000-a000-000000000002', 'Petite céréale d''Afrique de l''Ouest à la cuisson rapide et au goût léger, pour accompagner les sauces.', 'Le fonio est une toute petite céréale cultivée depuis très longtemps en Afrique de l''Ouest, notamment au Mali, en Guinée, au Burkina Faso et au Sénégal. Ses grains très fins cuisent en quelques minutes.

Son goût léger, entre noisette et semoule, en fait un accompagnement pour les sauces ; on le prépare aussi en salade ou en version sucrée.', 'Afrique de l''Ouest', null, null, array['/products/fonio.webp']::text[], 'Fonio (Digitaria exilis).', '{}'::text[], 'Suivre le temps de cuisson indiqué sur l''emballage : en général, cuire à la vapeur ou dans l''eau bouillante salée, couvrir quelques minutes puis égrener à la fourchette.', 'Au sec, dans un contenant fermé.', array['céréale ancienne']::text[], 'B0C78LFHJS', true, true, '2026-01-06T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000007', 'attieke-sec', 'Attiéké déshydraté', '10000000-0000-4000-a000-000000000002', 'La semoule de manioc fermenté de Côte d''Ivoire, en version séchée à réhydrater en quelques minutes.', 'L''attiéké est une semoule de manioc fermenté au goût légèrement acidulé, emblématique de la cuisine ivoirienne. La version déshydratée se conserve longtemps et se réhydrate en quelques minutes.

Il accompagne traditionnellement le poisson braisé ou frit, avec des oignons, de la tomate et du piment.', 'Côte d''Ivoire', null, null, array['/products/attieke-sec.webp']::text[], 'Manioc fermenté, séché.', '{}'::text[], 'Suivre les indications de l''emballage : en général, humidifier, laisser gonfler quelques minutes puis réchauffer à la vapeur. Servir avec oignons, tomates et piment.', 'Au sec, dans un contenant fermé.', array['manioc', 'fermenté']::text[], 'B0CCLHXJFJ', true, false, '2026-01-07T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000008', 'couscous-de-mil', 'Couscous de mil (thiéré)', '10000000-0000-4000-a000-000000000002', 'Couscous de mil pour le thiéré et le thiakry, deux classiques de la cuisine sénégalaise.', 'Au Sénégal, la farine de mil est roulée en petits grains puis cuite à la vapeur pour donner le thiéré, un couscous au goût plus rustique que la semoule de blé.

Il accompagne les plats en sauce comme le thiéré mbuum et sert aussi au thiakry, un dessert au lait caillé.', 'Sénégal', null, null, array['/products/couscous-de-mil.webp']::text[], 'Mil ; voir l''étiquette pour la composition exacte.', '{}'::text[], 'Cuire à la vapeur, de préférence en deux fois, en égrenant les grains entre les deux cuissons.', 'Au sec, dans un contenant fermé.', array['mil']::text[], 'B0DWKQHXLN', true, false, '2026-01-08T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000009', 'feuilles-de-ndole', 'Feuilles de ndolé séchées', '10000000-0000-4000-a000-000000000003', 'Feuilles de ndolé séchées pour préparer le plat du même nom, emblème de la cuisine camerounaise.', 'Le ndolé désigne à la fois une plante aux feuilles amères (Vernonia) et le plat camerounais qu''on en tire, cuisiné avec des arachides, de la viande, du poisson ou des crevettes. Séchées, les feuilles se conservent longtemps.

Avant la cuisson, on les réhydrate et on les rince pour atténuer leur amertume, puis on les fait mijoter dans la sauce d''arachide.', 'Cameroun', null, null, array['/products/feuilles-de-ndole.webp']::text[], 'Feuilles de Vernonia séchées.', '{}'::text[], 'Réhydrater dans l''eau tiède, rincer plusieurs fois puis presser avant de cuisiner, en suivant aussi les indications de l''emballage.', 'Au sec, à l''abri de la lumière.', array['feuilles', 'Cameroun']::text[], 'B0FQQXJ23P', true, true, '2026-01-09T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000000a', 'feuilles-de-manioc', 'Feuilles de manioc pilées (pondu, ravitoto)', '10000000-0000-4000-a000-000000000003', 'Feuilles de manioc pilées en conserve, prêtes à cuisiner pour le pondu, le saka-saka ou le ravitoto.', 'Les feuilles de manioc pilées sont la base du pondu (ou saka-saka) des deux Congo et du ravitoto malgache. En conserve ou en bocal, elles sont déjà pilées et prêtes à être cuisinées.

On les fait mijoter avec de l''huile de palme, de l''oignon, de l''ail et souvent du poisson fumé ; à Madagascar, le ravitoto se cuisine avec de la viande de porc.', null, null, null, array['/products/feuilles-de-manioc.webp']::text[], 'Feuilles de manioc pilées ; voir l''étiquette pour la composition exacte.', '{}'::text[], 'Faire mijoter avec l''huile de palme, les aromates et le poisson ou la viande, en suivant le temps de cuisson indiqué sur l''emballage.', 'Tant que le contenant est fermé : à température ambiante. Une fois entamé : au frais, dans un récipient fermé, et à utiliser rapidement.', array['feuilles', 'manioc']::text[], 'B092379XP9', true, false, '2026-01-10T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000000b', 'fleurs-de-bissap', 'Fleurs de bissap', '10000000-0000-4000-a000-000000000003', 'Calices d''hibiscus séchés pour préparer le bissap, la boisson rouge rubis d''Afrique de l''Ouest.', 'Les fleurs de bissap sont les calices séchés de l''Hibiscus sabdariffa. Infusés, ils donnent une boisson d''un rouge profond, au goût acidulé et fruité, très populaire en Afrique de l''Ouest, notamment au Sénégal.

Le bissap se sert sucré et bien frais, parfumé à la menthe, à la vanille ou à la fleur d''oranger ; les fleurs entrent aussi dans certaines sauces et confitures.', 'Afrique de l''Ouest', null, null, array['/products/fleurs-de-bissap.webp']::text[], 'Calices d''Hibiscus sabdariffa séchés.', '{}'::text[], 'Infuser à froid une nuit ou à chaud 10 minutes, filtrer, sucrer et parfumer à la menthe ou à la fleur d''oranger.', 'Au sec, à l''abri de la lumière.', array['boisson', 'hibiscus']::text[], 'B09LMHFX9T', true, true, '2026-01-11T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000000c', 'guedj', 'Guedj (poisson séché fermenté)', '10000000-0000-4000-a000-000000000004', 'Poisson fermenté puis séché, utilisé en petite quantité pour donner du goût au thiéboudienne.', 'Le guedj est un poisson fermenté puis séché, très utilisé dans la cuisine sénégalaise. Son odeur est puissante, c''est normal : on n''en utilise qu''un petit morceau.

Il donne au thiéboudienne, au yassa et à de nombreuses sauces un goût profond et iodé.', 'Sénégal', null, null, array['/products/guedj.webp']::text[], 'Poisson fermenté et séché ; peut contenir du sel, voir l''étiquette.', array['poisson']::text[], 'Rincer, puis ajouter un morceau dans la sauce en début de cuisson.', 'Au sec, dans une boîte hermétique.', array['poisson', 'fermenté']::text[], 'B0DK3SVDJN', true, false, '2026-01-12T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000000d', 'crevettes-sechees', 'Crevettes séchées', '10000000-0000-4000-a000-000000000004', 'Petites crevettes séchées qui relèvent le ndolé, les sauces gombo et les soupes, entières ou moulues.', 'Les crevettes séchées sont un ingrédient courant des cuisines d''Afrique de l''Ouest et centrale. Séchées, parfois fumées, elles concentrent un goût marin prononcé.

On les utilise entières ou moulues pour relever le ndolé, les sauces gombo, les sauces feuilles et les soupes.', null, null, null, array['/products/crevettes-sechees.webp']::text[], 'Crevettes séchées ; peut contenir du sel, voir l''étiquette.', array['crustacés']::text[], 'Rincer rapidement, puis ajouter entières en fin de cuisson ou moudre dans la sauce.', 'Au sec, dans une boîte hermétique.', array['crustacés']::text[], 'B0BVGJQC39', true, false, '2026-01-13T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000000e', 'poisson-fume', 'Machoiron fumé', '10000000-0000-4000-a000-000000000004', 'Poisson-chat fumé, utilisé pour parfumer le pondu, les sauces graine et les plats de légumes feuilles.', 'Le machoiron est un poisson-chat que l''on fume pour le conserver. Sa chair ferme prend un goût fumé prononcé.

Émietté, il parfume le pondu, les sauces graine et les plats de légumes feuilles d''Afrique centrale et de l''Ouest.', null, null, null, array['/products/poisson-fume.webp']::text[], 'Poisson-chat fumé.', array['poisson']::text[], 'Tremper 15 minutes dans l''eau chaude, retirer les arêtes et émietter dans la sauce.', 'Au sec et au frais, dans une boîte hermétique.', array['fumé', 'poisson']::text[], null, false, false, '2026-01-14T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000000f', 'huile-de-palme-rouge', 'Huile de palme rouge', '10000000-0000-4000-a000-000000000005', 'Huile de palme rouge non raffinée, au goût fruité, base de nombreuses sauces d''Afrique de l''Ouest et centrale.', 'L''huile de palme rouge est extraite de la pulpe des fruits du palmier à huile. Non raffinée, elle garde sa couleur orangée et son goût fruité caractéristique.

Elle est la base du pondu, de la sauce graine, de l''eru et de nombreux plats d''Afrique de l''Ouest et centrale.', null, null, null, array['/products/huile-de-palme-rouge.webp']::text[], 'Huile de palme rouge.', '{}'::text[], 'Chauffer doucement sans la faire fumer. Elle fige au frais : c''est normal.', 'À température ambiante, à l''abri de la lumière.', array['palme']::text[], 'B0962X7DNX', true, false, '2026-01-15T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000010', 'pate-d-arachide', 'Pâte d''arachide', '10000000-0000-4000-a000-000000000005', 'Pâte d''arachides grillées pour préparer le mafé, les sauces d''arachide et la soupe d''arachide.', 'La pâte d''arachide est obtenue en broyant des arachides grillées jusqu''à former une pâte épaisse. Selon les marques, elle peut contenir du sel ou de l''huile végétale.

C''est l''ingrédient clé du mafé, de la soupe d''arachide du Ghana et de nombreuses sauces d''Afrique de l''Ouest et centrale.', null, null, null, array['/products/pate-d-arachide.webp']::text[], 'Arachides grillées, peut contenir sel et huile végétale selon la marque ; voir l''étiquette.', array['arachide']::text[], 'Délayer dans un peu de bouillon chaud avant de l''ajouter à la sauce.', 'À température ambiante, pot bien fermé. Remuer avant usage si l''huile est remontée à la surface.', array['arachide']::text[], 'B07VX8JBYN', true, true, '2026-01-16T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000011', 'pulpe-de-noix-de-palme', 'Pulpe de noix de palme (800 g)', '10000000-0000-4000-a000-000000000005', 'Crème de noix de palme prête à cuisiner, pour la sauce graine, le poulet nyembwe et la soupe de noix de palme.', 'La pulpe de noix de palme est extraite des noix de palme cuites et pilées. Onctueuse et orangée, elle évite la longue préparation des noix fraîches.

Elle sert de base à la sauce graine de Côte d''Ivoire, au poulet nyembwe du Gabon, à la palm nut soup du Ghana ou au banga du Nigeria.', null, null, null, array['/products/pulpe-de-noix-de-palme.webp']::text[], 'Pulpe de noix de palme ; voir l''étiquette pour la composition exacte.', '{}'::text[], 'Diluer dans l''eau et faire réduire lentement avec la viande ou le poisson jusqu''à ce que l''huile remonte.', 'Tant que le contenant est fermé : à température ambiante. Une fois entamé : au frais, dans un récipient fermé, et à utiliser rapidement.', array['palme']::text[], 'B07C1KX53F', true, false, '2026-01-17T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000012', 'graines-d-egusi', 'Egusi moulu (pistache africaine)', '10000000-0000-4000-a000-000000000001', 'Graines d''egusi moulues, pour épaissir et parfumer la soupe egusi du Nigeria et du Ghana.', 'L''egusi, parfois appelé pistache africaine, désigne les graines de certaines courges et melons d''Afrique de l''Ouest. Moulues, elles ont un goût doux qui rappelle la noisette.

Elles épaississent et parfument la soupe egusi, un grand classique du Nigeria et du Ghana, servie avec le fufu, l''eba ou l''amala.', 'Afrique de l''Ouest', null, null, array['/products/graines-d-egusi.webp']::text[], 'Graines d''egusi moulues.', '{}'::text[], 'Délayer la poudre avec un peu d''eau, puis l''ajouter à la sauce et laisser cuire jusqu''à former de petits grumeaux moelleux.', 'Au sec, dans un contenant fermé.', array['graines', 'egusi']::text[], 'B0DLV721PS', true, true, '2026-01-18T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000013', 'gombo-seche', 'Gombo séché en poudre', '10000000-0000-4000-a000-000000000003', 'Gombo séché et moulu, pour donner à la sauce gombo sa texture filante, même hors saison.', 'Le gombo séché en poudre est obtenu à partir de gombos coupés, séchés puis moulus. Cette poudre permet de préparer la sauce gombo toute l''année.

Au Sahel, elle donne sa texture filante à la sauce qui accompagne le tô ; on l''utilise aussi dans les soupes et les sauces d''Afrique de l''Ouest.', null, null, null, array['/products/gombo-seche.webp']::text[], 'Gombo (Abelmoschus esculentus) séché et moulu.', '{}'::text[], 'Verser en pluie dans la sauce frémissante en fouettant, puis cuire 5 minutes.', 'Au sec, à l''abri de la lumière.', array['gombo', 'Sahel']::text[], 'B0C66R4FWK', true, false, '2026-01-19T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000014', 'feuilles-de-moringa', 'Feuilles de moringa séchées', '10000000-0000-4000-a000-000000000003', 'Feuilles de moringa séchées, le nébédaye du Sénégal, pour le thiéré mbuum et les sauces feuilles.', 'Le moringa est un arbre dont les feuilles sont très utilisées en cuisine en Afrique de l''Ouest. Au Sénégal, on les appelle nébédaye.

Séchées, elles parfument le thiéré mbuum, un couscous de mil aux feuilles et à l''arachide, ainsi que diverses sauces feuilles, avec un goût herbacé.', null, null, null, array['/products/feuilles-de-moringa.webp']::text[], 'Feuilles de moringa (Moringa oleifera) séchées.', '{}'::text[], 'Réhydrater quelques minutes puis ajouter dans la sauce ou le couscous en fin de cuisson.', 'Au sec, à l''abri de la lumière.', array['feuilles', 'Sénégal']::text[], 'B086JBQJ1J', true, false, '2026-01-20T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000015', 'feuilles-de-sorgho', 'Feuilles de sorgho rouge (waakye)', '10000000-0000-4000-a000-000000000003', 'Feuilles de sorgho séchées qui donnent au waakye ghanéen sa couleur brun-rouge caractéristique.', 'Au Ghana, le waakye, un plat de riz et de haricots, cuit avec des feuilles de sorgho séchées. Elles lui donnent sa couleur brun-rouge caractéristique et un léger parfum.

Les feuilles ne se mangent pas : on les retire avant de servir. Le waakye s''accompagne de sauce pimentée, d''œufs, de gari ou de spaghettis.', 'Ghana', null, null, array['/products/feuilles-de-sorgho.webp']::text[], 'Feuilles de sorgho séchées.', '{}'::text[], 'Rincer, ajouter à l''eau de cuisson du riz et des haricots, puis retirer avant de servir.', 'Au sec, dans un contenant fermé.', array['feuilles', 'Ghana']::text[], 'B0F922WGDC', true, false, '2026-01-21T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000016', 'feuilles-d-okok', 'Feuilles d''okok émincées', '10000000-0000-4000-a000-000000000003', 'Feuilles d''okok émincées et séchées, pour préparer l''eru et les plats de légumes du Cameroun.', 'L''okok, ou eru, est une liane des forêts d''Afrique centrale dont les feuilles se consomment émincées très finement. Séchées, elles se conservent longtemps.

Au Cameroun, elles se cuisinent avec de l''huile de palme, de la viande, du poisson fumé ou des crevettes séchées.', 'Cameroun', null, null, array['/products/feuilles-d-okok.webp']::text[], 'Feuilles de Gnetum africanum émincées et séchées.', '{}'::text[], 'Réhydrater dans l''eau tiède avant de cuisiner, en suivant les indications de l''emballage.', 'Au sec, à l''abri de la lumière.', array['feuilles', 'forêt']::text[], null, false, false, '2026-01-22T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000017', 'odika', 'Odika (chocolat indigène)', '10000000-0000-4000-a000-000000000005', 'Pain d''amandes de mangue sauvage, surnommé chocolat indigène, qui épaissit les sauces gabonaises.', 'L''odika est préparé à partir des amandes de la mangue sauvage (Irvingia gabonensis), grillées puis pressées en un pain sombre. On le surnomme parfois « chocolat indigène » pour son aspect.

Râpé dans les sauces, il leur donne une couleur brune, une texture onctueuse et un goût fumé ; c''est un ingrédient phare de la cuisine gabonaise.', 'Gabon', null, null, array['/products/odika.webp']::text[], 'Amandes de mangue sauvage (Irvingia gabonensis) grillées et pressées.', array['fruits à coque']::text[], 'Râper ou chauffer légèrement pour ramollir, puis délayer dans la sauce en fin de cuisson.', 'Au sec et au frais, emballé.', array['Gabon', 'forêt']::text[], null, false, true, '2026-01-23T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000018', 'farine-de-teff', 'Farine de teff', '10000000-0000-4000-a000-000000000002', 'Farine de teff, la petite céréale éthiopienne qui sert à préparer l''injera, la grande galette alvéolée.', 'Le teff est une céréale minuscule cultivée depuis très longtemps sur les hauts plateaux d''Éthiopie et d''Érythrée. Sa farine a un goût légèrement acidulé.

Fermentée quelques jours, elle donne l''injera, la grande galette alvéolée qui sert à la fois d''assiette et de couvert pour les wats ; on l''utilise aussi en pâtisserie.', 'Éthiopie', null, null, array['/products/farine-de-teff.webp']::text[], 'Farine de teff (Eragrostis tef).', '{}'::text[], 'Mélanger à l''eau et laisser fermenter 2 à 3 jours avant de cuire les injeras.', 'Au sec et au frais, dans un contenant fermé.', array['céréale ancienne', 'Éthiopie']::text[], 'B0C1TBB24S', true, true, '2026-01-24T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000019', 'poudre-de-baobab', 'Pain de singe (poudre de baobab)', '10000000-0000-4000-a000-000000000002', 'Pulpe de fruit du baobab en poudre, au goût acidulé, pour le jus de bouye et le ngalakh sénégalais.', 'Le fruit du baobab, appelé pain de singe, renferme une pulpe sèche et farineuse au goût acidulé. Réduite en poudre, elle se délaye facilement.

Au Sénégal, elle sert à préparer le jus de bouye et la crème du ngalakh, un dessert à base de mil et d''arachide ; elle parfume aussi les glaces et les pâtisseries.', null, null, null, array['/products/poudre-de-baobab.webp']::text[], 'Pulpe de fruit du baobab (Adansonia digitata) en poudre.', '{}'::text[], 'Délayer dans l''eau froide ou le lait, filtrer si besoin et sucrer à votre goût.', 'Au sec, dans un contenant fermé.', array['baobab', 'Sénégal']::text[], 'B06Y3L4CP1', true, false, '2026-01-25T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000001a', 'farine-de-foufou', 'Farine de manioc pour foufou', '10000000-0000-4000-a000-000000000002', 'Farine de manioc pour préparer rapidement un foufou lisse et élastique, sans piler au mortier.', 'La farine de manioc permet de préparer le foufou à la casserole, sans piler au mortier. Travaillée dans l''eau bouillante, elle donne une pâte lisse et élastique.

Le foufou accompagne les sauces et les soupes d''Afrique centrale et de l''Ouest : sauce feuilles, soupe egusi, sauce graine ou pondu.', null, null, null, array['/products/farine-de-foufou.webp']::text[], 'Farine de manioc.', '{}'::text[], 'Verser dans l''eau bouillante en remuant vigoureusement avec une spatule jusqu''à obtenir une pâte lisse.', 'Au sec, dans un contenant fermé.', array['manioc', 'foufou']::text[], 'B0DY1V2QVZ', true, false, '2026-01-26T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000001b', 'piment-pili-pili', 'Piment oiseau pili-pili entier', '10000000-0000-4000-a000-000000000001', 'Le petit piment rouge séché, très piquant, qui relève les sauces de Dakar à Kinshasa.', 'Petit, rouge vif et très piquant, le pili-pili (ou piment oiseau) est présent de Dakar à Kinshasa. Séché entier, il garde son parfum fruité et sa force.

On le jette entier dans les sauces pour une chaleur douce, ou on l''écrase au mortier pour un piquant franc. Il sert aussi de base aux huiles pimentées maison.', 'Afrique', null, null, array['/products/piment-pili-pili.webp']::text[], 'Piments oiseau (Capsicum frutescens) séchés entiers.', '{}'::text[], 'Ajouter un ou deux piments entiers dans le mafé ou le yassa et les retirer avant de servir si l''on veut un piquant modéré. Se laver les mains après manipulation.', 'Au sec, à l''abri de la lumière, dans un contenant fermé.', array['piment', 'piquant']::text[], 'B092VLDV68', true, false, '2026-01-27T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000001c', 'bitter-kola', 'Bitter kola (petites noix)', '10000000-0000-4000-a000-000000000008', 'La noix amère que l''on partage lors des visites et des cérémonies en Afrique de l''Ouest.', 'Le bitter kola est la graine du Garcinia kola, un arbre des forêts d''Afrique de l''Ouest et centrale. Brune et ferme, elle a une amertume franche suivie d''une note légèrement astringente.

Au Nigeria, on l''offre aux invités et on la croque lors des rencontres et des cérémonies traditionnelles, souvent avec la noix de kola. Un produit de tradition plus que de cuisine.', 'Nigeria', null, null, array['/products/bitter-kola.webp']::text[], 'Noix de bitter kola (Garcinia kola).', '{}'::text[], 'Retirer la fine peau brune, puis croquer la noix nature, en petits morceaux. Son amertume se marie bien avec une boisson fraîche.', 'Au frais et au sec, dans un sachet ou un bocal fermé.', array['noix', 'tradition', 'Nigeria']::text[], 'B09YPZ3T11', true, false, '2026-01-28T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000001d', 'cafe-touba', 'Café Touba', '10000000-0000-4000-a000-000000000006', 'Le café épicé au poivre de Selim, servi à tous les coins de rue du Sénégal.', 'Né à Touba, ville sainte du mouridisme, le café Touba est un café torréfié avec du djar, le poivre de Selim. Il en ressort une boisson sombre aux notes poivrées, boisées et légèrement fumées.

Au Sénégal, il se boit très sucré, préparé au filtre en tissu et servi dans de petits gobelets, du matin au soir.', 'Sénégal', 'Touba', null, array['/products/cafe-touba.webp']::text[], 'Café torréfié et moulu, poivre de Selim (djar).', '{}'::text[], 'Préparer au filtre, avec une cuillère de café Touba par tasse, et sucrer généreusement comme au Sénégal.', 'Au sec, à l''abri de la lumière, dans un contenant fermé.', array['café', 'Sénégal', 'épicé']::text[], 'B0B52RYJS8', true, false, '2026-01-29T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000001e', 'farine-d-igname', 'Farine d''igname (amala / elubo)', '10000000-0000-4000-a000-000000000002', 'La farine d''igname séchée qui donne l''amala, la pâte brune des Yoruba.', 'L''elubo est une farine obtenue à partir d''igname épluchée, séchée puis moulue. Travaillée dans l''eau bouillante, elle donne l''amala, une pâte souple à la couleur brune caractéristique.

Au sud-ouest du Nigeria, l''amala accompagne l''ewedu, le gbegiri et les sauces au poisson ou à la viande.', 'Nigeria', null, null, array['/products/farine-d-igname.webp']::text[], 'Igname séchée et moulue.', '{}'::text[], 'Verser la farine en pluie dans l''eau bouillante en tournant vivement à la spatule jusqu''à obtenir une pâte lisse et élastique.', 'Au sec, dans un contenant fermé.', array['igname', 'amala', 'Nigeria']::text[], 'B08CF5G29P', true, false, '2026-01-30T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000001f', 'akpi-djansang', 'Akpi / djansang (graines)', '10000000-0000-4000-a000-000000000001', 'Petites graines au goût de noisette qui épaississent et parfument les sauces.', 'L''akpi, appelé djansang au Cameroun, est la graine du Ricinodendron heudelotii, un grand arbre des forêts d''Afrique de l''Ouest et centrale. Torréfiées et moulues, les graines ont un goût doux de noisette et de sésame.

On l''utilise pour lier et parfumer les sauces, les marinades de poisson braisé et les sauces tomate.', 'Côte d''Ivoire / Cameroun', null, null, array['/products/akpi-djansang.webp']::text[], 'Graines d''akpi (Ricinodendron heudelotii) séchées.', '{}'::text[], 'Torréfier légèrement à sec, puis moudre ou écraser au mortier avant de les ajouter à la sauce ou à la marinade du poisson braisé.', 'Au sec, à l''abri de la lumière, dans un contenant fermé.', array['graines', 'sauce', 'Cameroun']::text[], 'B0CP9SPRP8', true, false, '2026-01-31T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000020', 'assaisonnement-jollof', 'Assaisonnement jollof', '10000000-0000-4000-a000-000000000001', 'Un mélange d''épices prêt à l''emploi pour donner au riz jollof sa couleur et son parfum.', 'Le riz jollof, riz rouge cuit dans une sauce tomate épicée, se dispute entre le Nigeria et le Ghana. Ce mélange réunit les épices et aromates qui lui donnent sa couleur et son parfum.

Il permet de réussir un jollof bien assaisonné sans multiplier les pots d''épices.', 'Nigeria / Ghana', null, null, array['/products/assaisonnement-jollof.webp']::text[], 'Mélange d''épices et d''aromates.', '{}'::text[], 'Ajouter à la base tomate-oignon-piment une fois qu''elle a bien réduit, avant d''y verser le riz et le bouillon.', 'Au sec, à l''abri de la lumière, dans un contenant fermé.', array['mélange', 'riz', 'jollof']::text[], 'B0B8135LLS', true, false, '2026-02-01T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000021', 'maniguette', 'Maniguette (graines de paradis)', '10000000-0000-4000-a000-000000000001', 'Des graines au piquant poivré et aux notes d''agrumes, cousines de la cardamome.', 'La maniguette, ou graine de paradis, pousse en gousses sur l''Aframomum melegueta, une plante des côtes d''Afrique de l''Ouest. Ses petites graines brunes offrent un piquant proche du poivre, avec des notes citronnées et florales.

Elle parfume les sauces, les grillades et les bouillons, et se moud comme un poivre.', 'Côte d''Ivoire', null, null, array['/products/maniguette.webp']::text[], 'Gousses de maniguette (Aframomum melegueta).', '{}'::text[], 'Ouvrir la gousse, écraser les graines au mortier et les ajouter en fin de cuisson sur les viandes et poissons grillés.', 'Au sec, à l''abri de la lumière, dans un contenant fermé.', array['poivre', 'graines']::text[], 'B0DR681HDS', true, false, '2026-02-02T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000022', 'essesse-sassas', 'Essessè / sassas en poudre', '10000000-0000-4000-a000-000000000001', 'Une épice camerounaise au parfum boisé et sucré pour les bouillons et sauces.', 'L''essessè est une épice de la cuisine camerounaise, séchée puis réduite en poudre. Elle apporte un parfum boisé, légèrement sucré et fumé.

On l''associe au pèbè et au djansang dans les épices des soupes, des bouillons de poisson et des sauces jaunes.', 'Cameroun', null, null, array['/products/essesse-sassas.webp']::text[], 'Épice d''essessè séchée et moulue.', '{}'::text[], 'En ajouter une petite pincée dans le bouillon en début de cuisson, avec les autres épices à soupe.', 'Au sec, à l''abri de la lumière, dans un contenant fermé.', array['épice', 'Cameroun', 'soupe']::text[], 'B0CG9Z9QDN', true, false, '2026-02-03T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000023', 'infusion-de-tamarin', 'Infusion de tamarin', '10000000-0000-4000-a000-000000000006', 'Le goût acidulé et fruité du tamarin, en sachets à infuser, pour une boisson chaude ou glacée.', 'Le tamarin, ou dakhar au Sénégal, est la gousse d''un grand arbre des savanes. Sa pulpe acidulée et fruitée sert aussi bien aux boissons qu''aux sauces.

Cette infusion en sachets permet de retrouver facilement la saveur du jus de tamarin, chaude ou froide.', 'Sénégal', null, null, array['/products/infusion-de-tamarin.webp']::text[], 'Tamarin séché, en sachets à infuser.', '{}'::text[], 'Infuser un sachet dans l''eau chaude, sucrer à son goût ; se boit aussi bien glacé, avec quelques feuilles de menthe.', 'Au sec, à l''abri de la lumière, dans un contenant fermé.', array['infusion', 'tamarin', 'Sénégal']::text[], 'B079VNZ645', true, false, '2026-02-04T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000024', 'infusion-de-gingembre', 'Infusion de gingembre', '10000000-0000-4000-a000-000000000006', 'Le piquant du gingembre, en sachets, pour une boisson chaude ou glacée.', 'En Côte d''Ivoire, le gingembre se boit en jus, le gnamankoudji, très relevé et bien sucré. Cette infusion en sachets en reprend la saveur piquante, en version plus simple à préparer.

Elle se boit chaude, ou refroidie avec du citron et de la menthe.', null, null, null, array['/products/infusion-de-gingembre.webp']::text[], 'Gingembre séché, en sachets à infuser.', '{}'::text[], 'Infuser un sachet dans l''eau chaude, ajouter un trait de citron et du sucre ou du miel selon le goût.', 'Au sec, à l''abri de la lumière, dans un contenant fermé.', array['infusion', 'gingembre']::text[], 'B079VNZ641', true, false, '2026-02-05T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000025', 'chips-de-plantain', 'Chips de plantain', '10000000-0000-4000-a000-000000000008', 'Fines tranches de banane plantain frites, croustillantes et légèrement salées.', 'Vendues au bord des routes de Douala à Accra, les chips de plantain sont faites de fines tranches de banane plantain frites jusqu''à devenir bien croustillantes.

Elles se grignotent à l''apéritif ou accompagnent une boisson fraîche, un jus de bissap ou de gingembre.', 'Afrique de l''Ouest et centrale', null, null, array['/products/chips-de-plantain.webp']::text[], 'Banane plantain, huile végétale, sel.', '{}'::text[], 'À servir nature à l''apéritif, ou avec une sauce pimentée pour tremper.', 'Au sec ; une fois le sachet ouvert, bien refermer et consommer rapidement.', array['plantain', 'apéritif', 'snack']::text[], 'B0C6YLBNM4', true, false, '2026-02-06T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000026', 'gari-jaune', 'Gari jaune (semoule de manioc)', '10000000-0000-4000-a000-000000000002', 'Semoule de manioc fermenté et torréfié, pour l''eba ou à boire à l''eau fraîche.', 'Le gari est obtenu en râpant du manioc, en le laissant fermenter, puis en le torréfiant en fines graines croquantes. La version jaune doit sa couleur à l''huile de palme ajoutée pendant la cuisson.

Au Bénin, au Nigeria et au Ghana, on le travaille dans l''eau chaude pour faire l''eba, ou on le trempe dans l''eau froide avec du sucre et des arachides.', 'Bénin / Nigeria / Ghana', null, null, array['/products/gari-jaune.webp']::text[], 'Manioc fermenté, râpé et torréfié, huile de palme.', '{}'::text[], 'Pour l''eba : verser le gari dans l''eau bouillante, laisser gonfler puis malaxer à la spatule. Servir avec une sauce gombo ou egusi.', 'Au sec, dans un contenant fermé.', array['manioc', 'gari', 'eba']::text[], 'B0D5BX4R97', true, false, '2026-02-07T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000027', 'farine-de-plantain-pour-fufu', 'Farine de plantain pour fufu', '10000000-0000-4000-a000-000000000002', 'Une farine de plantain séché pour préparer le fufu à la casserole, sans piler au mortier.', 'Au Ghana, le fufu se pile traditionnellement au mortier à partir de plantain et de manioc cuits. Cette farine de plantain séché permet d''obtenir une pâte lisse directement à la casserole.

Le fufu accompagne les soupes légères : soupe d''arachide, light soup, soupe de noix de palme.', 'Ghana', null, null, array['/products/farine-de-plantain-pour-fufu.webp']::text[], 'Farine de banane plantain.', '{}'::text[], 'Délayer la farine dans l''eau froide, puis cuire à feu moyen en tournant sans cesse jusqu''à obtenir une pâte ferme et lisse.', 'Au sec, dans un contenant fermé.', array['plantain', 'fufu', 'Ghana']::text[], 'B00MWVXFC0', true, false, '2026-02-08T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000028', 'chikwangue', 'Chikwangue (bâton de manioc)', '10000000-0000-4000-a000-000000000002', 'Le pain de manioc fermenté des deux Congo, cuit dans des feuilles, pour accompagner les sauces.', 'La chikwangue, ou kwanga, est une pâte de manioc fermenté façonnée en bâton, enveloppée dans des feuilles puis cuite à la vapeur. Sa texture est ferme et élastique, son goût légèrement acidulé.

En RD Congo et au Congo, elle accompagne le poisson grillé, le pondu, la moambé et toutes les sauces.', 'RD Congo / Congo', null, null, array['/products/chikwangue.webp']::text[], 'Manioc fermenté.', '{}'::text[], 'Retirer les feuilles, couper en tranches et servir tel quel ou réchauffé à la vapeur, avec du poisson braisé ou une sauce.', 'Suivre les indications de l''emballage ; une fois ouverte, conserver au frais et consommer rapidement.', array['manioc', 'Congo', 'fermenté']::text[], 'B0FPPTF2D9', true, false, '2026-02-09T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000029', 'tapioca-de-manioc', 'Tapioca de manioc granulé', '10000000-0000-4000-a000-000000000002', 'Des granules de manioc à gonfler dans l''eau, pour les desserts, les bouillies et les boissons.', 'Le tapioca granulé est tiré de l''amidon de manioc, humidifié puis roulé en petits grains. Dans l''eau, il gonfle et devient translucide.

En Afrique de l''Ouest et centrale, on le prépare en bouillie sucrée, trempé dans l''eau froide avec du lait et du sucre, ou dans des desserts à la noix de coco.', 'Afrique de l''Ouest et centrale', null, null, array['/products/tapioca-de-manioc.webp']::text[], 'Manioc granulé.', '{}'::text[], 'Tremper dans l''eau froide ou chaude jusqu''à ce qu''il gonfle, puis ajouter du lait, du sucre et éventuellement des arachides grillées.', 'Au sec, dans un contenant fermé.', array['manioc', 'dessert']::text[], 'B0D1P648SL', true, false, '2026-02-10T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000002a', 'pebe-moulu', 'Pèbè moulu (muscade africaine)', '10000000-0000-4000-a000-000000000001', 'La muscade africaine, chaude et parfumée, pour les soupes et les grillades.', 'Le pèbè est la graine du Monodora myristica, un arbre des forêts tropicales. Moulue, elle rappelle la noix de muscade, avec des notes plus douces et légèrement épicées.

Au Cameroun, elle entre dans les épices du poisson braisé, du pèpè soupe et de nombreuses sauces.', 'Cameroun', null, null, array['/products/pebe-moulu.webp']::text[], 'Graines de pèbè (Monodora myristica) moulues.', '{}'::text[], 'Mélanger à l''ail, au gingembre et au djansang pour mariner le poisson braisé, ou en ajouter une pincée dans le bouillon.', 'Au sec, à l''abri de la lumière, dans un contenant fermé.', array['épice', 'Cameroun', 'muscade']::text[], 'B0BV7HBJWZ', true, false, '2026-02-11T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000002b', 'biltong', 'Biltong', '10000000-0000-4000-a000-000000000008', 'La viande de bœuf séchée et épicée d''Afrique du Sud, à grignoter en fines lamelles à l''apéritif.', 'Le biltong est une viande marinée dans le vinaigre et les épices (coriandre, poivre, sel), puis séchée à l''air. Tradition sud-africaine, il se déguste en fines lamelles, à la main.

On le sert à l''apéritif, lors des braais, ou en randonnée ; il s''émiette aussi dans les salades et les pâtes.', 'Afrique du Sud', null, null, array['/products/biltong.webp']::text[], 'Viande de bœuf, vinaigre, sel, épices (coriandre, poivre).', '{}'::text[], 'Trancher finement et servir à température ambiante, en apéritif ou en accompagnement d''une salade.', 'Au sec et au frais ; une fois le paquet ouvert, conserver au frais et consommer rapidement.', array['viande séchée', 'Afrique du Sud', 'apéritif']::text[], 'B06VTJD4RF', true, false, '2026-02-12T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000002c', 'sauce-graine-nkulenus', 'Crème de noix de palme (palm nut)', '10000000-0000-4000-a000-000000000005', 'La base de sauce graine et de soupe de noix de palme, prête à cuisiner.', 'La sauce graine se prépare à partir de la pulpe des noix de palme, longuement bouillies et pilées. Cette crème de palme évite toute cette étape et donne une sauce onctueuse, orangée et parfumée.

Elle sert pour la sauce graine ivoirienne, la palm nut soup ghanéenne ou le banga nigérian, avec poisson fumé, viande ou crabe.', 'Ghana', null, null, array['/products/sauce-graine-nkulenus.webp']::text[], 'Pulpe de noix de palme.', '{}'::text[], 'Délayer la pulpe dans de l''eau chaude, porter à ébullition puis laisser mijoter avec la viande ou le poisson fumé jusqu''à ce que l''huile remonte.', 'Au sec tant que la boîte est fermée ; ensuite, au frais dans un contenant fermé et à utiliser rapidement.', array['palme', 'sauce graine']::text[], 'B0DZJPCQ6B', true, false, '2026-02-13T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000002d', 'feuilles-de-baobab', 'Feuilles de baobab séchées (lalo)', '10000000-0000-4000-a000-000000000003', 'La poudre de feuilles de baobab qui lie le couscous et les sauces du Sahel.', 'Le lalo est fait de feuilles de baobab séchées puis réduites en poudre verte. Il donne une texture légèrement filante et un goût herbacé discret.

Au Sénégal, on l''ajoute au thiéré (couscous de mil) pour le rendre souple ; au Mali, il sert à préparer des sauces feuilles.', 'Sénégal / Mali', null, null, array['/products/feuilles-de-baobab.webp']::text[], 'Feuilles de baobab (Adansonia digitata) séchées et moulues.', '{}'::text[], 'Pour le thiéré, délayer une cuillère de lalo dans un peu d''eau et en humecter le couscous avant la cuisson à la vapeur.', 'Au sec, à l''abri de la lumière, dans un contenant fermé.', array['baobab', 'feuilles', 'Sénégal']::text[], 'B0DFWZ6FR9', true, false, '2026-02-14T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000002e', 'vanille-bourbon-de-madagascar', 'Vanille bourbon de Madagascar', '10000000-0000-4000-a000-000000000001', 'Des gousses de vanille souples et parfumées, de la côte nord-est de Madagascar.', 'La vanille bourbon est cultivée à Madagascar, où chaque fleur est fécondée à la main. Les gousses sont ensuite échaudées, étuvées et séchées lentement pour développer leur arôme.

Elle parfume les desserts, les crèmes, le rhum arrangé, mais aussi certaines sauces pour le poisson ou les crustacés.', 'Madagascar', 'Sava', null, array['/products/vanille-bourbon-de-madagascar.webp']::text[], 'Gousses de vanille (Vanilla planifolia).', '{}'::text[], 'Fendre la gousse, gratter les graines et les infuser dans le lait chaud ; la gousse vidée peut parfumer un bocal de sucre.', 'Dans un tube ou un bocal hermétique, au frais et à l''abri de la lumière (pas au réfrigérateur).', array['vanille', 'Madagascar', 'dessert']::text[], 'B0949LGX4T', true, false, '2026-02-15T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000002f', 'sauce-peri-peri', 'Sauce peri-peri', '10000000-0000-4000-a000-000000000001', 'La sauce pimentée au citron et à l''ail, héritée de la cuisine du Mozambique.', 'Le peri-peri est un petit piment africain qui a donné son nom à une sauce née au Mozambique et devenue emblématique en Afrique du Sud. Piment, citron, ail et vinaigre composent une sauce vive et piquante.

Elle accompagne surtout le poulet grillé, mais aussi les crevettes, le poisson et les frites.', 'Afrique du Sud / Mozambique', null, null, array['/products/sauce-peri-peri.webp']::text[], 'Piment, vinaigre, citron, ail, sel, épices.', '{}'::text[], 'Badigeonner le poulet avant de le griller, puis en napper de nouveau à la sortie du feu.', 'Au frais une fois ouverte, bouchon bien fermé.', array['piment', 'sauce', 'grillade']::text[], 'B0019MEJPA', true, false, '2026-02-16T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000030', 'poivre-sauvage-voatsiperifery', 'Poivre sauvage voatsiperifery', '10000000-0000-4000-a000-000000000001', 'Un poivre sauvage à queue de Madagascar, cueilli en forêt, aux notes boisées et d''agrumes.', 'Le voatsiperifery est un poivre sauvage qui pousse sur des lianes dans les forêts de Madagascar. Ses baies à petite queue sont cueillies à la main, puis séchées.

Son piquant est plus doux que celui du poivre noir, avec des notes fraîches, boisées et légèrement citronnées.', 'Madagascar', null, null, array['/products/poivre-sauvage-voatsiperifery.webp']::text[], 'Baies de poivre sauvage (Piper borbonense) séchées.', '{}'::text[], 'Moudre au dernier moment sur les poissons, les viandes blanches, les légumes ou même les fruits.', 'Au sec, à l''abri de la lumière, dans un contenant fermé.', array['poivre', 'cueillette', 'Madagascar']::text[], 'B08M49PCY9', true, false, '2026-02-17T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000031', 'ras-el-hanout', 'Ras el hanout', '10000000-0000-4000-a000-000000000001', 'Le mélange d''épices marocain, chaud et parfumé, des tajines et couscous.', 'Ras el hanout signifie « la tête de l''épicerie » : chaque épicier compose son propre mélange avec ses meilleures épices. Cumin, coriandre, cannelle, gingembre, curcuma et poivre en forment souvent la base.

Il parfume les tajines, les couscous, les marinades de viande et les légumes rôtis.', 'Maroc', null, null, array['/products/ras-el-hanout.webp']::text[], 'Mélange d''épices.', '{}'::text[], 'Faire revenir une cuillère de ras el hanout dans l''huile avec les oignons avant d''ajouter la viande du tajine.', 'Au sec, à l''abri de la lumière, dans un contenant fermé.', array['mélange', 'Maroc', 'tajine']::text[], 'B08QZ7P9LL', true, false, '2026-02-18T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000032', 'souchet', 'Souchet (noix tigrée)', '10000000-0000-4000-a000-000000000008', 'Petits tubercules sucrés au goût de noisette, pour les boissons et les en-cas.', 'Malgré son nom de noix tigrée, le souchet est un petit tubercule cultivé en Afrique de l''Ouest. Il a un goût sucré qui rappelle l''amande et la noisette.

Au Nigeria, on le mixe pour préparer le kunun aya, une boisson lactée ; ailleurs, on le grignote simplement après l''avoir fait tremper.', 'Afrique de l''Ouest', null, null, array['/products/souchet.webp']::text[], 'Tubercules de souchet (Cyperus esculentus) séchés.', '{}'::text[], 'Faire tremper une nuit, puis mixer avec de l''eau, des dattes et un peu de gingembre ; filtrer pour obtenir une boisson lactée.', 'Au sec, dans un contenant fermé.', array['souchet', 'boisson', 'tubercule']::text[], 'B01LAY7LN8', true, false, '2026-02-19T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000033', 'epices-tunisiennes', 'Épices tunisiennes (lot)', '10000000-0000-4000-a000-000000000001', 'Un assortiment d''épices et de mélanges pour cuisiner le couscous et la chakchouka à la tunisienne.', 'Carvi, coriandre, piment, tabel : la cuisine tunisienne aime les épices franches. Ce lot réunit plusieurs épices et mélanges du pays pour composer ses propres assaisonnements.

Il sert pour le couscous, la chakchouka, les ragoûts de légumes et les marinades de poisson.', 'Tunisie', null, null, array['/products/epices-tunisiennes.webp']::text[], 'Assortiment d''épices et de mélanges d''épices.', '{}'::text[], 'Faire revenir les épices quelques instants dans l''huile d''olive avant d''ajouter la tomate, pour libérer leur parfum.', 'Au sec, à l''abri de la lumière, dans un contenant fermé.', array['épices', 'Tunisie', 'assortiment']::text[], 'B0CQVWV82R', true, false, '2026-02-20T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000034', 'dukkah', 'Dukkah', '10000000-0000-4000-a000-000000000001', 'Le mélange égyptien de fruits à coque, graines et épices, à tremper avec du pain.', 'Le dukkah est un mélange égyptien de fruits à coque torréfiés, de graines de sésame et d''épices comme la coriandre et le cumin, grossièrement concassés.

On le sert traditionnellement avec du pain trempé dans l''huile d''olive, mais il enrobe aussi très bien les légumes, les salades et les poissons.', 'Égypte', null, null, array['/products/dukkah.webp']::text[], 'Fruits à coque, graines de sésame, épices, sel.', array['fruits à coque', 'sésame']::text[], 'Tremper un morceau de pain dans l''huile d''olive puis dans le dukkah, ou en parsemer une salade ou des légumes rôtis.', 'Au sec, à l''abri de la lumière, dans un contenant fermé.', array['mélange', 'Égypte', 'apéritif']::text[], 'B08HY51WZC', true, false, '2026-02-21T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000035', 'dattes-deglet-nour', 'Dattes Deglet Nour', '10000000-0000-4000-a000-000000000008', 'Des dattes Deglet Nour dorées et translucides, à la chair fondante et au goût de miel.', 'La Deglet Nour, « doigt de lumière », est la variété de dattes phare de Tunisie. Sa chair blonde et translucide a une texture fondante et un goût de miel.

Elles se dégustent nature, avec du lait ou du thé, et entrent dans les tajines sucrés-salés, les couscous et les pâtisseries.', 'Tunisie', 'Djérid', null, array['/products/dattes-deglet-nour.webp']::text[], 'Dattes Deglet Nour.', '{}'::text[], 'Dénoyauter et farcir de pâte d''amande, ou ajouter aux tajines d''agneau en fin de cuisson.', 'Au frais et au sec, dans une boîte fermée.', array['dattes', 'Tunisie', 'fruits secs']::text[], 'B01MQKD9BU', true, false, '2026-02-22T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000036', 'mortier-et-pilon-en-bois', 'Mortier et pilon en bois d''acacia', '10000000-0000-4000-a000-000000000007', 'Le mortier en bois d''acacia pour piler épices, ail, piment, arachides grillées et feuilles.', 'Dans les cuisines africaines, le mortier en bois est un outil du quotidien. En acacia, bois dense et solide, il permet d''écraser épices, ail, piment, arachides grillées ou feuilles.

Sa taille le destine aux préparations de tous les jours, pour les pâtes d''épices et les petites quantités.', null, null, null, array['/products/mortier-et-pilon-en-bois.webp']::text[], null, '{}'::text[], 'Piler l''ail, le gingembre et le piment pour le yassa, ou les arachides grillées. Laver à l''eau chaude sans tremper, bien sécher et huiler de temps en temps.', null, array['mortier', 'bois', 'épices']::text[], 'B0972M8VRF', true, false, '2026-02-23T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000037', 'huile-d-argan', 'Huile d''argan alimentaire', '10000000-0000-4000-a000-000000000005', 'L''huile aux notes de noisette grillée, pressée à partir des amandons d''argan.', 'L''arganier ne pousse qu''au sud-ouest du Maroc. Les amandons de ses fruits sont torréfiés puis pressés pour donner une huile dorée au goût de noisette grillée.

Elle s''utilise crue : sur les salades, le couscous, les tajines en fin de cuisson, ou dans l''amlou avec les amandes et le miel.', 'Maroc', 'Souss', null, array['/products/huile-d-argan.webp']::text[], 'Huile vierge d''amandons d''argan torréfiés.', '{}'::text[], 'Utiliser crue, en filet sur un couscous, des légumes ou du pain chaud ; éviter de la chauffer pour garder son goût.', 'À l''abri de la lumière et de la chaleur, bouteille bien fermée.', array['huile', 'Maroc', 'argan']::text[], 'B07H516MRQ', true, false, '2026-02-24T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000038', 'citrons-beldi-confits', 'Citrons beldi confits', '10000000-0000-4000-a000-000000000005', 'Les petits citrons beldi confits au sel, incontournables du tajine de poulet aux olives.', 'Le citron beldi est une petite variété marocaine à peau fine et parfumée. Confit dans le sel, il perd son acidité et prend un goût doux et intense.

Il est indispensable au tajine de poulet aux olives, et relève aussi les salades, les poissons et les sauces.', 'Maroc', null, null, array['/products/citrons-beldi-confits.webp']::text[], 'Citrons beldi, sel, eau.', '{}'::text[], 'Rincer, retirer la pulpe si on la trouve trop salée, puis couper l''écorce en lanières et l''ajouter au tajine en fin de cuisson.', 'Au frais une fois le pot ouvert, les citrons bien couverts de leur saumure.', array['citron', 'Maroc', 'tajine']::text[], 'B07ZBZYJ7W', true, false, '2026-02-25T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000039', 'harissa-artisanale', 'Harissa artisanale', '10000000-0000-4000-a000-000000000001', 'La pâte de piment rouge tunisienne, piquante et parfumée au carvi, pour le couscous et la chakchouka.', 'La harissa est une pâte de piments rouges séchés, pilés avec de l''ail, du sel et des épices comme le carvi et la coriandre, puis couverte d''huile.

En Tunisie, elle est partout : dans le couscous, la chakchouka, les sandwichs, ou simplement tartinée sur du pain avec de l''huile d''olive.', 'Tunisie', null, null, array['/products/harissa-artisanale.webp']::text[], 'Piments rouges, ail, épices, sel, huile.', '{}'::text[], 'Délayer une cuillère dans un peu de bouillon de couscous, ou la servir à part, arrosée d''huile d''olive.', 'Au frais une fois le pot ouvert, recouverte d''un filet d''huile.', array['piment', 'Tunisie', 'pâte']::text[], 'B0CPMDRB3T', true, false, '2026-02-26T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000003a', 'marmite-en-aluminium', 'Marmite en aluminium type caldero', '10000000-0000-4000-a000-000000000007', 'Une marmite en aluminium épais pour le riz : thiéboudienne, jollof, riz gras.', 'Sa fonte d''aluminium épaisse répartit bien la chaleur et favorise au fond la formation du xoon, le riz légèrement croustillant si recherché au Sénégal.

Parfaite pour le thiéboudienne, le riz jollof ou le riz gras, elle sert aussi pour les ragoûts et les sauces.', null, null, null, array['/products/marmite-en-aluminium.webp']::text[], null, '{}'::text[], 'Cuire le riz à feu doux, couvercle fermé, pour obtenir un fond doré. Laver à l''eau chaude savonneuse et bien sécher ; éviter le lave-vaisselle.', null, array['marmite', 'riz', 'thiéboudienne']::text[], 'B00164U4G4', true, false, '2026-02-27T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000003b', 'marmite-potjie', 'Marmite en fonte à trois pieds (potjie)', '10000000-0000-4000-a000-000000000007', 'La marmite en fonte sud-africaine qui se pose directement sur les braises.', 'Le potjie est une marmite ventrue en fonte, montée sur trois pieds, héritée des cuisines de plein air d''Afrique du Sud. Posée sur les braises, elle mijote lentement viande, légumes et épices.

Le potjiekos, ragoût en couches cuit sans remuer, en est le plat emblématique ; elle convient aussi au mafé ou aux ragoûts cuits au feu de bois.', 'Afrique du Sud', null, null, array['/products/marmite-potjie.webp']::text[], null, '{}'::text[], 'Superposer viande, légumes et épices sans remuer et laisser mijoter doucement sur les braises. Après usage, laver à l''eau chaude, sécher au feu et huiler légèrement l''intérieur.', null, array['fonte', 'feu de bois', 'Afrique du Sud']::text[], 'B0CZXS1ZHN', true, false, '2026-02-28T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000003c', 'mortier-en-granit', 'Mortier et pilon en granit 14 cm', '10000000-0000-4000-a000-000000000007', 'Un mortier en granit lourd et stable pour écraser piment, ail, gingembre et épices en graines.', 'Le granit, lourd et non poreux, écrase efficacement les aromates frais sans glisser. Ce mortier de taille moyenne est idéal pour les pâtes d''épices.

On y prépare la base ail-gingembre-piment des marinades, les pâtes de piment frais ou les mélanges d''épices en graines.', null, null, null, array['/products/mortier-en-granit.webp']::text[], null, '{}'::text[], 'Écraser ail, gingembre, piment et oignon pour les marinades de poulet yassa ou de poisson braisé. Rincer à l''eau chaude et laisser sécher à l''air.', null, array['mortier', 'granit', 'épices']::text[], 'B0BD8NMF5C', true, false, '2026-03-01T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000003d', 'couscoussier', 'Couscoussier inox', '10000000-0000-4000-a000-000000000007', 'Le couscoussier pour cuire à la vapeur le fonio, le thiéré et l''attiéké.', 'Le couscoussier associe une marmite et un panier percé qui s''emboîte au-dessus. La sauce ou l''eau mijote en bas pendant que la semoule cuit à la vapeur en haut.

Il sert au couscous du Maghreb comme aux semoules d''Afrique de l''Ouest : fonio, thiéré de mil, attiéké.', 'Afrique du Nord', null, null, array['/products/couscoussier.webp']::text[], null, '{}'::text[], 'Humidifier la semoule, la cuire à la vapeur dans le panier, l''égrener puis la remettre à cuire une seconde fois. Laver à l''eau chaude savonneuse et bien sécher.', null, array['vapeur', 'couscous', 'fonio']::text[], 'B000VWV6QO', true, false, '2026-03-02T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000003e', 'faitout-en-fonte-d-aluminium', 'Faitout en fonte d''aluminium 28 cm', '10000000-0000-4000-a000-000000000007', 'Un grand faitout en fonte d''aluminium pour les plats mijotés : mafé, ndolé, yassa ou ragoûts.', 'La fonte d''aluminium chauffe vite et répartit la chaleur de façon homogène, sans être aussi lourde que la fonte de fer.

C''est l''allié des plats qui mijotent longtemps : mafé, ndolé, yassa, sauces feuilles ou ragoûts.', null, null, null, array['/products/faitout-en-fonte-d-aluminium.webp']::text[], null, '{}'::text[], 'Faire revenir oignons et viande à feu moyen, puis laisser mijoter à feu doux, couvercle posé. Laver à l''eau chaude avec une éponge non abrasive.', null, array['faitout', 'mijoté', 'mafé']::text[], 'B075V8SPZ3', true, false, '2026-03-03T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000003f', 'tamis-en-bois', 'Tamis en bois 20 cm maille fine', '10000000-0000-4000-a000-000000000007', 'Un tamis à maille fine pour les farines de teff, de foufou ou le fonio.', 'Le tamis à cadre en bois est un outil classique des cuisines africaines pour affiner les farines et séparer les grains.

Il sert à tamiser la farine de teff pour l''injera, les farines de foufou ou de maïs, et à égrener le fonio ou le couscous de mil.', null, null, null, array['/products/tamis-en-bois.webp']::text[], null, '{}'::text[], 'Tamiser la farine au-dessus d''un grand saladier en tapotant le cadre. Brosser à sec après usage et laisser sécher à l''air.', null, array['tamis', 'farine', 'fonio']::text[], 'B08DHNY6D5', true, false, '2026-03-04T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000040', 'plaque-a-injera', 'Plaque de cuisson électrique 30 cm', '10000000-0000-4000-a000-000000000007', 'Une grande plaque électrique de 30 cm pour cuire l''injera éthiopienne, les galettes et les crêpes.', 'L''injera, la grande crêpe fermentée de teff d''Éthiopie et d''Érythrée, se cuit sur une large plaque bien chaude. Cette plaque électrique permet de la préparer à la maison.

Elle convient aussi aux crêpes de mil, aux galettes et aux crêpes sucrées.', null, null, null, array['/products/plaque-a-injera.webp']::text[], null, '{}'::text[], 'Verser la pâte en spirale du bord vers le centre, couvrir et cuire sans retourner. Nettoyer à l''aide d''un chiffon humide une fois la plaque refroidie.', null, array['injera', 'crêpes', 'Éthiopie']::text[], 'B0DD39QLC9', true, false, '2026-03-05T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000041', 'brochettes-en-metal', 'Brochettes en métal 40 cm (lot de 30)', '10000000-0000-4000-a000-000000000007', 'De longues brochettes métalliques réutilisables pour le suya, les dibi et toutes les grillades.', 'Le suya, la brochette épicée des rues du Nigeria, se grille sur de longues piques au-dessus des braises. Ces brochettes en métal réutilisables conviennent au barbecue comme au four.

Elles servent aussi aux dibi, aux brochettes de poisson ou de légumes.', null, null, null, array['/products/brochettes-en-metal.webp']::text[], null, '{}'::text[], 'Enfiler de fines lamelles de viande enrobées de yaji et griller au-dessus des braises. Laver à l''eau chaude savonneuse et bien sécher.', null, array['brochettes', 'suya', 'grillade']::text[], 'B0GWY2YH3X', true, false, '2026-03-06T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000042', 'verres-a-the', 'Verres à thé facettés 210 ml (lot de 6)', '10000000-0000-4000-a000-000000000007', 'Les petits verres facettés de l''ataya et du thé à la menthe, pour servir le thé avec sa mousse.', 'Au Sénégal, en Mauritanie comme au Maroc, le thé se sert dans de petits verres facettés. On y fait passer le thé d''un verre à l''autre pour former la mousse.

Ce lot de six verres accompagne la théière pour les trois services de l''ataya.', null, null, null, array['/products/verres-a-the.webp']::text[], null, '{}'::text[], 'Verser le thé de haut pour former une belle mousse. Laver à l''eau chaude savonneuse et essuyer pour garder la transparence.', null, array['verres', 'ataya', 'thé']::text[], 'B0BWNVD37T', true, false, '2026-03-07T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000043', 'tajine-en-argile', 'Tajine touareg en argile 30 cm', '10000000-0000-4000-a000-000000000007', 'Le plat en terre à couvercle conique des mijotés d''Afrique du Nord, pour cuire et servir à table.', 'Le tajine est à la fois un plat de cuisson et de service : son couvercle conique renvoie la vapeur vers les aliments, qui cuisent doucement dans leur jus.

Il sert aux tajines de poulet aux citrons confits, d''agneau aux pruneaux ou de légumes, et peut se poser sur la table.', 'Afrique du Nord', null, null, array['/products/tajine-en-argile.webp']::text[], null, '{}'::text[], 'Cuire à feu doux, idéalement avec un diffuseur, en évitant les chocs de température. Laver à l''eau chaude sans détergent et laisser bien sécher.', null, array['tajine', 'argile', 'Afrique du Nord']::text[], 'B0077C6XDC', true, false, '2026-03-08T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000044', 'theiere-a-ataya', 'Théière marocaine inox 1,2 L', '10000000-0000-4000-a000-000000000007', 'La théière à long bec pour servir de haut le thé à la menthe et l''ataya, avec une belle mousse.', 'Sa forme ventrue et son bec verseur allongé permettent de servir le thé de haut pour former la mousse. On peut la poser directement sur le feu.

Elle est utilisée aussi bien pour le thé à la menthe marocain que pour l''ataya sénégalais.', 'Maroc', null, null, array['/products/theiere-a-ataya.webp']::text[], null, '{}'::text[], 'Faire bouillir le thé vert directement dans la théière, ajouter sucre et menthe, puis servir de haut. Rincer à l''eau chaude et bien sécher.', null, array['théière', 'ataya', 'thé à la menthe']::text[], 'B0DJVCC3C6', true, false, '2026-03-09T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000045', 'passoire-a-couscous', 'Passoire à couscous 23 cm', '10000000-0000-4000-a000-000000000007', 'Une passoire qui s''adapte sur une marmite pour cuire à la vapeur le couscous, le fonio ou l''attiéké.', 'Posée sur une marmite, cette passoire devient un panier vapeur pour le couscous, le fonio ou l''attiéké. Elle sert aussi simplement à égoutter.

Une bonne solution pour cuire les semoules à la vapeur sans couscoussier dédié.', null, null, null, array['/products/passoire-a-couscous.webp']::text[], null, '{}'::text[], 'Poser sur une marmite de même diamètre et calfeutrer la jointure avec un torchon humide pour que la vapeur passe par la semoule. Laver à l''eau chaude savonneuse.', null, array['vapeur', 'passoire', 'couscous']::text[], 'B07QQLZ5ML', true, false, '2026-03-10T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000046', 'rechaud-a-charbon-jiko', 'Réchaud à charbon type jiko', '10000000-0000-4000-a000-000000000007', 'Le réchaud à charbon kényan, pour cuisiner et griller sur les braises.', 'Le jiko est le réchaud à charbon de bois des cuisines d''Afrique de l''Est. Ce modèle moderne concentre la chaleur des braises pour cuire, mijoter ou griller.

Il convient aux grillades, au nyama choma, au maïs grillé et aux plats qui mijotent sur le feu.', 'Kenya', null, null, array['/products/rechaud-a-charbon-jiko.webp']::text[], null, '{}'::text[], 'À utiliser uniquement à l''extérieur ou dans un lieu très bien aéré. Vider les cendres une fois refroidies et brosser la grille.', null, array['charbon', 'grillade', 'Kenya']::text[], 'B0BCXN4K59', true, false, '2026-03-11T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000047', 'araignee-a-friture', 'Araignée à friture 14 cm', '10000000-0000-4000-a000-000000000007', 'L''écumoire à large panier pour sortir de l''huile l''alloco, les puff-puff, les accras et les beignets.', 'Avec son large panier en fils métalliques, l''araignée permet de retirer les fritures de l''huile en les égouttant aussitôt.

Indispensable pour l''alloco, les puff-puff, les accras de haricots ou les beignets de banane.', null, null, null, array['/products/araignee-a-friture.webp']::text[], null, '{}'::text[], 'Retourner et sortir les beignets de l''huile chaude, puis les poser sur du papier absorbant. Laver à l''eau chaude savonneuse et bien sécher.', null, array['friture', 'beignets', 'alloco']::text[], 'B001FWQ5DS', true, false, '2026-03-12T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000048', 'spatules-en-bois', 'Spatules en bois (lot de 8)', '10000000-0000-4000-a000-000000000007', 'Des spatules en bois solides pour tourner le tô, le foufou et l''amala, et remuer les sauces.', 'Tourner une pâte de tô, de foufou ou d''amala demande un ustensile solide qui ne rayera pas la marmite. Ce lot de spatules en bois couvre tous les usages.

Elles servent aussi pour remuer les sauces, le riz et les mijotés.', null, null, null, array['/products/spatules-en-bois.webp']::text[], null, '{}'::text[], 'Tourner vivement la pâte contre la paroi de la marmite pour la rendre lisse. Laver à la main, bien sécher et huiler de temps en temps.', null, array['spatules', 'bois', 'foufou']::text[], 'B006677VQ2', true, false, '2026-03-13T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000049', 'saladier-en-bois', 'Grand saladier en bois d''acacia 26 cm', '10000000-0000-4000-a000-000000000007', 'Un grand saladier en bois d''acacia pour le service, les salades et le plat commun à partager.', 'Dans de nombreuses cuisines africaines, on partage le repas autour d''un plat commun. Ce grand saladier en acacia s''y prête bien, tout comme au service des salades et des fruits.

Il met en valeur le thiakry, l''attiéké ou une salade d''avocat.', null, null, null, array['/products/saladier-en-bois.webp']::text[], null, '{}'::text[], 'Servir le plat commun ou une salade ; éviter les liquides très chauds. Laver rapidement à la main, sécher et huiler de temps en temps.', null, array['saladier', 'bois', 'service']::text[], 'B004IZ20MO', true, false, '2026-03-14T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000004a', 'bouilloire-emaillee', 'Bouilloire émaillée 2,4 L', '10000000-0000-4000-a000-000000000007', 'Une bouilloire émaillée à poser sur le feu, pour l''eau chaude du thé, du café et des infusions.', 'Les bouilloires émaillées colorées font partie du paysage de nombreuses cuisines africaines. Posée directement sur le feu, elle chauffe l''eau du thé et des infusions.

Elle convient pour préparer le kinkeliba, le thé à la menthe ou le café Touba.', null, null, null, array['/products/bouilloire-emaillee.webp']::text[], null, '{}'::text[], 'Chauffer sur le feu à flamme moyenne, sans la laisser à vide. Rincer et sécher après usage ; éviter les éponges abrasives sur l''émail.', null, array['bouilloire', 'thé', 'émail']::text[], 'B08LKKM6C9', true, false, '2026-03-15T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000004b', 'feuilles-de-bananier-fraiches', 'Feuilles de bananier fraîches (lot de 100)', '10000000-0000-4000-a000-000000000007', 'Les grandes feuilles pour envelopper le koki, le liboké et les papillotes.', 'En Afrique centrale et de l''Ouest, la feuille de bananier sert d''emballage de cuisson : elle protège les aliments et leur donne un léger parfum végétal.

On l''utilise pour le koki de haricots, le liboké de poisson, les papillotes et pour tapisser le fond des marmites.', null, null, null, array['/products/feuilles-de-bananier-fraiches.webp']::text[], 'Feuilles de bananier fraîches.', '{}'::text[], 'Passer rapidement les feuilles au-dessus d''une flamme ou dans l''eau chaude pour les assouplir, puis y envelopper la préparation et ficeler.', 'Au frais, enveloppées ; se conservent aussi au congélateur.', array['bananier', 'papillote', 'koki']::text[], 'B0D2H42WZ2', true, false, '2026-03-16T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000004c', 'cafe-du-kivu', 'Café moulu du Kivu (RD Congo)', '10000000-0000-4000-a000-000000000006', 'Un café arabica moulu des rives du lac Kivu, à l''est de la RD Congo, rond et fruité.', 'Autour du lac Kivu, à l''est de la RD Congo, les caféiers poussent en altitude sur des sols volcaniques. Le café qui en est issu est rond, avec des notes fruitées et une belle douceur.

Moulu, il convient à la cafetière filtre et à la cafetière italienne.', 'RD Congo', 'Kivu', null, array['/products/cafe-du-kivu.webp']::text[], 'Café arabica torréfié et moulu.', '{}'::text[], 'Préparer au filtre ou à la cafetière italienne ; bien refermer le paquet après chaque usage.', 'Au sec, à l''abri de la lumière, dans un contenant fermé.', array['café', 'RD Congo', 'arabica']::text[], 'B074ZLR7JD', true, false, '2026-03-17T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000004d', 'cafe-vert-du-cameroun', 'Café vert du Cameroun à torréfier', '10000000-0000-4000-a000-000000000006', 'Des grains de café vert pour torréfier soi-même, comme à la maison au Cameroun.', 'Dans l''Ouest du Cameroun, de nombreuses familles torréfient encore leur café à la poêle. Ces grains verts, non torréfiés, permettent de retrouver ce geste et de choisir son degré de torréfaction.

Une fois grillés, ils se moulent et se préparent comme n''importe quel café.', 'Cameroun', null, null, array['/products/cafe-vert-du-cameroun.webp']::text[], 'Grains de café vert non torréfiés.', '{}'::text[], 'Torréfier par petites quantités à la poêle épaisse, en remuant sans cesse jusqu''à la couleur souhaitée, puis laisser reposer avant de moudre.', 'Au sec, à l''abri de la lumière, dans un contenant fermé.', array['café vert', 'Cameroun', 'torréfaction']::text[], 'B0FJH3F4D4', true, false, '2026-03-18T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000004e', 'cafe-moka-sidamo', 'Café moulu Moka Sidamo', '10000000-0000-4000-a000-000000000006', 'Un café moka moulu de la région de Sidamo, au sud de l''Éthiopie, à la tasse florale et fruitée.', 'L''Éthiopie est le berceau de l''arabica. Dans la région de Sidamo, au sud du pays, le café pousse en altitude et offre une tasse florale, fruitée et délicate.

Moulu, il se prépare au filtre et peut accompagner une cérémonie du café à la maison.', 'Éthiopie', 'Sidamo', null, array['/products/cafe-moka-sidamo.webp']::text[], 'Café arabica torréfié et moulu.', '{}'::text[], 'Préparer au filtre ou à la cafetière à piston ; en Éthiopie, on le sert parfois avec une pincée de sel ou de cardamome.', 'Au sec, à l''abri de la lumière, dans un contenant fermé.', array['café', 'Éthiopie', 'moka']::text[], 'B01BSY1IDO', true, false, '2026-03-19T00:00:00.000Z'),
  ('20000000-0000-4000-a000-00000000004f', 'cafe-du-kenya', 'Café en grains du Kenya', '10000000-0000-4000-a000-000000000006', 'Un café arabica du Kenya en grains, cultivé sur les hauts plateaux, à la tasse vive et fruitée.', 'Les cafés du Kenya poussent sur les hauts plateaux, au pied du mont Kenya. Ils sont réputés pour leur acidité vive et leurs notes de fruits rouges et d''agrumes.

En grains, ils gardent tout leur parfum jusqu''à la mouture.', 'Kenya', null, null, array['/products/cafe-du-kenya.webp']::text[], 'Café arabica torréfié en grains.', '{}'::text[], 'Moudre juste avant la préparation, plutôt grossièrement pour la cafetière à piston ou le filtre.', 'Au sec, à l''abri de la lumière, dans un contenant fermé.', array['café', 'Kenya', 'grains']::text[], 'B0FHBR3X7S', true, false, '2026-03-20T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000050', 'cafe-harrar', 'Café en grains Éthiopie Harrar', '10000000-0000-4000-a000-000000000006', 'Un café éthiopien de l''est du pays, aux notes fruitées et chocolatées.', 'La région de Harrar, à l''est de l''Éthiopie, produit un café séché dans son fruit, au soleil. Il en ressort une tasse corsée, fruitée, avec des notes de cacao.

C''est l''un des cafés les plus typés d''Éthiopie.', 'Éthiopie', 'Harrar', null, array['/products/cafe-harrar.webp']::text[], 'Café arabica torréfié en grains.', '{}'::text[], 'Moudre juste avant la préparation ; il convient particulièrement à la cafetière italienne et à l''expresso.', 'Au sec, à l''abri de la lumière, dans un contenant fermé.', array['café', 'Éthiopie', 'grains']::text[], 'B0FJHDJKKX', true, false, '2026-03-21T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000051', 'cafe-yirgacheffe', 'Café en grains Yirgacheffe', '10000000-0000-4000-a000-000000000006', 'Un café éthiopien en grains de la région de Yirgacheffe, léger, floral et aux notes d''agrumes.', 'Yirgacheffe, dans le sud de l''Éthiopie, est l''une des régions de café les plus réputées au monde. Ses cafés lavés offrent une tasse légère, aux notes de fleurs blanches et d''agrumes.

Un café à découvrir de préférence en méthode douce.', 'Éthiopie', 'Yirgacheffe', null, array['/products/cafe-yirgacheffe.webp']::text[], 'Café arabica torréfié en grains.', '{}'::text[], 'Moudre juste avant la préparation et préparer au filtre ou à la cafetière à piston pour garder ses arômes délicats.', 'Au sec, à l''abri de la lumière, dans un contenant fermé.', array['café', 'Éthiopie', 'floral']::text[], 'B0CCYFVSTV', true, false, '2026-03-22T00:00:00.000Z'),
  ('20000000-0000-4000-a000-000000000052', 'cafe-du-cameroun', 'Café en grains du Cameroun (Bamoun)', '10000000-0000-4000-a000-000000000006', 'Un café arabica en grains du pays Bamoun, sur les hauts plateaux de l''Ouest camerounais.', 'Le pays Bamoun, dans l''Ouest du Cameroun, cultive l''arabica sur des terres d''altitude. Il donne un café équilibré, avec du corps et des notes chocolatées.

